const Store = {
  read(key, fallback) { try { const raw = localStorage.getItem(key); return raw == null ? fallback : JSON.parse(raw); } catch (e) { return fallback; } },
  write(key, val) { try { localStorage.setItem(key, JSON.stringify(val)); return { ok: true }; } catch (e) { return { ok: false, error: (e && (e.name || e.message)) || 'erro desconhecido' }; } },
  remove(key) { try { localStorage.removeItem(key); return { ok: true }; } catch (e) { return { ok: false, error: e && e.name }; } },
  available() { try { const k = 'm360.probe'; localStorage.setItem(k, '1'); localStorage.removeItem(k); return true; } catch (e) { return false; } },
  has(key) { try { return localStorage.getItem(key) != null; } catch (e) { return false; } }
};
