function slugKey(v) { return String(v || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,55); }
function normalizeProductTerm(v) { return String(v || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(); }
function productSimilarity(a, b) {
  const x = normalizeProductTerm(a), y = normalizeProductTerm(b);
  if (!x || !y) return 0;
  const prev = Array.from({length:y.length+1},(_,i)=>i);
  for (let i=1;i<=x.length;i++) { let diag=prev[0]; prev[0]=i; for (let j=1;j<=y.length;j++) { const old=prev[j]; prev[j]=Math.min(prev[j]+1,prev[j-1]+1,diag+(x[i-1]===y[j-1]?0:1)); diag=old; } }
  return Math.round((1-Math.max(0,prev[y.length])/Math.max(x.length,y.length))*100);
}
function selectedProducts(a) { return Array.isArray(a.context.products) ? a.context.products : []; }
function productQuestions(a) {
  const products = selectedProducts(a);
  return products.map(product => {
    const key = slugKey(product);
    return { id: 'prod_' + key, dim: 'processos', text: `Como a empresa controla o ciclo de vida de ${product.toLowerCase()} — requisitos de engenharia, materiais, fabricação ou fornecimento, inspeção, montagem, entrega e pós-venda?`, evidence: `Exemplo recente de ${product.toLowerCase()}: desenho ou especificação, roteiro/ordem, inspeções, rastreabilidade, entrega e registro de assistência.`, critical: false, mod: 'produto', product, check: 'Peça um pedido ou equipamento recente e percorra o fluxo desde a proposta até a entrega e o pós-venda.' };
  });
}
function contextualQuestions(a) {
  const qs = [];
  (a.context.branches || []).forEach(branch => {
    const bank = BRANCH_QUESTIONS[branch] || [];
    if (bank.length) bank.forEach(([id,dim,text,evidence,critical]) => qs.push({id,dim,text,evidence,critical:!!critical,mod:'ramo',branch,check:'Solicite um caso recente, documentos e indicadores que demonstrem a prática.'}));
    else qs.push({id:'ctx_branch_'+(slugKey(branch)||('custom_'+qs.length)),dim:'processos',text:`Quais particularidades técnicas, regulatórias, sazonais ou operacionais do ramo ${branch} mais influenciam a entrega ao cliente e como são gerenciadas?`,evidence:'Requisitos técnicos, normas aplicáveis, calendário operacional, contratos, indicadores e registros de atendimento.',critical:false,mod:'ramo',branch,check:'Peça um exemplo recente em que uma característica do ramo alterou prazo, custo, qualidade ou risco.'});
  });
  return qs.concat(productQuestions(a));
}

