  if (!(await ask('Importar dados da versão 2.4', `${parsed.assessments.length} avaliação(ões) serão adicionadas à lista. As respostas das 18 perguntas gerais são migradas; respostas de perguntas de segmento da v2.4 não, porque as perguntas mudaram. Os dados originais da v2.4 permanecem no navegador.`, 'Importar'))) return;
  const list = readList(); parsed.assessments.forEach(x => { x.savedAt = nowISO(); const i = list.findIndex(y => y && y.id === x.id); if (i >= 0) list[i] = x; else list.push(x); });
  const r = Store.write(KEYS.list, list); if (!r.ok) { toast('Falha ao gravar (' + r.error + '). Nada foi alterado.', 'err'); return; }
  renderSettings(); toast('Avaliações da v2.4 importadas.');
