/* ---------- Benchmarks ---------- */
function loadBench() {
  const d = Store.read(KEYS.bench, null);
  if (Array.isArray(d) && d.length) { const ok = []; d.forEach((r, i) => { try { ok.push(sanitizeBench(r, i)); } catch (e) { } }); if (ok.length) return ok; }
  return clone(BENCHMARK_SEED);
}
function saveBench() { const r = Store.write(KEYS.bench, BENCH); if (!r.ok) toast('Não foi possível salvar a base de benchmarks (' + r.error + '). Exporte a base em JSON.', 'err'); return r.ok; }
function benchFiltered() { const f = UI.benchFilter, q = f.q.trim().toLowerCase(); return BENCH.filter(r => (!q || [r.indicator, r.definition, r.comparability, r.source].join(' ').toLowerCase().includes(q)) && (!f.source || r.source === f.source) && (!f.status || r.validationStatus === f.status)); }
function benchChartSVG(rows) {
  if (!rows.length) return '<p class="fine">Sem registros para o indicador e os filtros escolhidos.</p>';
  const W = 620, left = 190, right = 80, top = 14, bh = 26, gap = 12, H = top + rows.length * (bh + gap) + 24, plot = W - left - right;
  const scales = new Set(rows.map(r => r.scaleMax)), common = scales.size === 1 && rows[0].scaleMax != null ? rows[0].scaleMax : null, max = common || Math.max(...rows.map(r => r.value)) || 1;
  const grid = [0, .25, .5, .75, 1].map(f => `<line class="grid-l" x1="${left + plot * f}" y1="${top - 4}" x2="${left + plot * f}" y2="${H - 18}"/><text class="axis" x="${left + plot * f}" y="${H - 4}" text-anchor="middle">${esc(fmtNum(max * f, max < 10 ? 1 : 0))}</text>`).join('');
  const bars = rows.map((r, i) => { const y = top + i * (bh + gap), w = Math.max(2, plot * r.value / max), lab = r.label.length > 28 ? r.label.slice(0, 26) + '…' : r.label; return `<g role="button" tabindex="0" data-action="bench-bar" data-ids="${esc(r.ids.join(','))}" aria-label="${esc(r.label)}: ${esc(String(r.value).replace('.', ','))} ${esc(r.unit)}. Filtrar a tabela."><title>${esc(r.label)}</title><text class="axis" x="${left - 8}" y="${y + 17}" text-anchor="end">${esc(lab)}</text><rect x="${left}" y="${y}" width="${w}" height="${bh}" rx="4" ${r.pending ? 'opacity=".45"' : ''}/><text class="val" x="${Math.min(left + w + 6, W - right + 4)}" y="${y + 17}">${esc(String(r.value).replace('.', ','))} ${esc(r.unit)}${r.pending ? ' (pendente)' : ''}</text></g>`; }).join('');
  return `<svg viewBox="0 0 ${W} ${H}" role="group" aria-label="Gráfico de barras do indicador selecionado">${grid}${bars}</svg><p class="fine">${common ? `Eixo na escala original da fonte (máximo ${esc(fmtNum(common, 0))}).` : 'Os registros têm escalas diferentes ou não confirmadas; o eixo usa o maior valor e as barras não devem ser comparadas entre si.'} Valores não são convertidos para a escala 1–5.</p>`;
}
function renderBench() {
  const vis = benchFiltered(), f = UI.benchFilter, srcs = [...new Set(BENCH.map(r => r.source))].sort();
  const inds = [...new Set(vis.map(r => r.indicator))].sort(); if (!inds.includes(UI.benchChart.indicator)) UI.benchChart.indicator = inds[0] || '';
  const g = UI.benchChart.group, chartRows = vis.filter(r => r.indicator === UI.benchChart.indicator).map(r => ({ label: String(r[g] ?? '—'), value: r.value, unit: r.unit, scaleMax: r.scaleMax, ids: [r.id], pending: r.validationStatus !== 'verificado' }));
  const ver = BENCH.filter(r => r.validationStatus === 'verificado').length;
  $('#benchHost').innerHTML = `<div class="panel-head"><div><h2>Referências e benchmarks</h2><p>Base separada da pontuação interna. Cada registro mantém valor, unidade e escala originais. Nenhuma escala externa é convertida para a escala 1–5. Registros pendentes não aparecem no relatório.</p></div></div>
  <div class="kpis"><div class="kpi"><span>Registros na base</span><strong>${BENCH.length}</strong></div><div class="kpi"><span>Verificados</span><strong>${ver}</strong><small>Conferidos na fonte, com data</small></div><div class="kpi"><span>Pendentes</span><strong>${BENCH.length - ver}</strong><small>Não usados no relatório</small></div><div class="kpi"><span>Após filtros</span><strong>${vis.length}</strong></div></div>
  <div class="grid three"><div class="field"><label for="bf-q">Buscar</label><input id="bf-q" data-bench="q" value="${esc(f.q)}" placeholder="Indicador, fonte ou observação"></div><div class="field"><label for="bf-source">Fonte</label><select id="bf-source" data-bench="source">${optList(srcs, f.source, 'Todas')}</select></div><div class="field"><label for="bf-status">Situação</label><select id="bf-status" data-bench="status">${optList([['verificado', 'Verificado'], ['pendente', 'Pendente']], f.status, 'Todas')}</select></div></div>
  <div class="btn-row" style="margin:10px 0"><button type="button" data-action="bench-export">Exportar base (JSON)</button><button type="button" data-action="bench-template">Baixar modelo CSV</button><button type="button" data-action="bench-import">Importar JSON ou CSV</button><input type="file" id="benchFile" accept=".json,.csv,application/json,text/csv" hidden><button type="button" data-action="bench-reset">Restaurar base inicial</button>${f.q || f.source || f.status ? '<button type="button" data-action="bench-clear">Limpar filtros</button>' : ''}</div>
  <div class="block bench-chart"><h4>Comparador por indicador</h4><div class="grid"><div class="field"><label for="bc-ind">Indicador</label><select id="bc-ind" data-benchchart="indicator">${optList(inds, UI.benchChart.indicator, null)}</select></div><div class="field"><label for="bc-group">Rótulo das barras</label><select id="bc-group" data-benchchart="group">${optList([['sector', 'Setor'], ['size', 'Porte'], ['source', 'Fonte'], ['year', 'Ano'], ['region', 'Região']], g, null)}</select></div></div><div style="overflow-x:auto">${benchChartSVG(chartRows)}</div></div>
  <div class="table-wrap"><table style="min-width:1100px"><thead><tr><th>Indicador e definição</th><th>Valor e escala</th><th>Fonte, ano e período</th><th>População e recorte</th><th>Margem de erro</th><th>Situação</th><th>Comparabilidade</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody>${vis.map(r => `<tr><td><b>${esc(r.indicator)}</b><div class="fine">${esc(r.definition)}</div></td><td><b>${esc(String(r.value).replace('.', ','))} ${esc(r.unit)}</b><div class="fine">${esc(r.scaleNote || (r.scaleMin != null && r.scaleMax != null ? `Escala ${r.scaleMin}–${r.scaleMax}` : 'Escala não informada'))}</div></td><td>${esc(r.source)} · ${esc(r.year)}<div class="fine">${esc(r.period || 'Período não informado')}</div>${r.sourceUrl ? `<a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">Publicação original</a>` : '<span class="fine">Sem link</span>'}</td><td>${esc(r.population || '—')}<div class="fine">Setor: ${esc(r.sector)} · Porte: ${esc(r.size || '—')} · Região: ${esc(r.region)}</div></td><td>${esc(r.marginError)}</td><td>${r.validationStatus === 'verificado' ? `<span class="tag ok">Verificado</span><div class="fine">${esc(fmtDate(r.validatedAt))}</div>` : '<span class="tag warn">Pendente</span>'}</td><td class="fine">${esc(r.comparability)}</td><td><button type="button" class="small danger" data-action="bench-del" data-id="${esc(r.id)}">Excluir</button></td></tr>`).join('') || '<tr><td colspan="8" class="fine">Nenhum registro com os filtros atuais.</td></tr>'}</tbody></table></div>
  <p class="fine" style="margin-top:8px">Importações entram como “pendente”, salvo quando o arquivo indicar “verificado” com data de validação. Links são aceitos apenas com http ou https. Confira cada valor, unidade e recorte na publicação original antes de marcar como verificado.</p>`;
}
const BENCH_FIELDS = ['id', 'indicator', 'definition', 'value', 'unit', 'scaleMin', 'scaleMax', 'scaleNote', 'source', 'sourceUrl', 'year', 'period', 'population', 'sector', 'size', 'region', 'marginError', 'validationStatus', 'validatedAt', 'comparability'];
async function importBenchFile(file) {
  let rows;
  try { const text = await readFileText(file); if (/\.csv$/i.test(file.name)) rows = parseCSV(text); else { let d; try { d = JSON.parse(text); } catch (e) { throw new Error('JSON inválido'); } rows = Array.isArray(d) ? d : d && Array.isArray(d.records) ? d.records : d && Array.isArray(d.benchmarks) ? d.benchmarks : null; if (!rows) throw new Error('não encontrei uma lista de registros'); } }
  catch (e) { toast('Falha ao importar benchmarks: ' + e.message + '.', 'err'); return; }
  if (rows.length > LIMITS.bench) { toast(`O arquivo tem mais de ${LIMITS.bench} registros.`, 'err'); return; }
  const ok = [], bad = []; rows.forEach((r, i) => { try { ok.push(sanitizeBench(r, i)); } catch (e) { bad.push(`Linha ${i + 2}: ${e.message}`); } });
  if (!ok.length) { toast('Nenhum registro válido. ' + bad.slice(0, 2).join(' '), 'err'); return; }
  const rep = ok.filter(r => BENCH.some(b => b.id === r.id)).length;
  if (!(await ask('Importar benchmarks', `${ok.length} registro(s) válido(s): ${ok.length - rep} novo(s) e ${rep} substituirão registros com o mesmo identificador.${bad.length ? `\n${bad.length} ignorado(s): ${bad.slice(0, 3).join('; ')}` : ''}`, 'Importar'))) return;
  const map = new Map(BENCH.map(r => [r.id, r])); ok.forEach(r => map.set(r.id, r)); const prev = BENCH; BENCH = [...map.values()];
  if (!saveBench()) { BENCH = prev; return; }
  renderBench(); toast(`${ok.length} registro(s) importado(s).`);
}

/* ---------- eventos ---------- */
function setBound(el) {
  const b = el.dataset.bind; let v = el.type === 'checkbox' ? el.checked : el.value;
  if (el.type === 'radio' && !el.checked) return;
  if ('num' in el.dataset) { if (v === '') v = ''; else { v = Number(v); const mn = el.min !== '' ? Number(el.min) : -Infinity, mx = el.max !== '' ? Number(el.max) : Infinity; if (!Number.isFinite(v) || v < mn || v > mx) { el.setAttribute('aria-invalid', 'true'); return; } el.removeAttribute('aria-invalid'); } }
  const parts = b.split(':');
  if (parts[0] === 'pref') {
    const k = parts[1];
    if (k === 'emailTo') { const okm = !v || /^[^\s@<>"']{1,64}@[^\s@<>"']{1,190}\.[^\s@<>"']{2,}$/.test(v); const er = $('#f-pref-emailTo-err'); el.setAttribute('aria-invalid', String(!okm)); if (er) er.textContent = okm ? '' : 'Informe um e-mail válido.'; if (!okm) return; }
    PREFS[k] = v; savePrefs();
    if (k === 'theme') applyTheme(v); if (k === 'logo') applyLogo(v); if (k === 'retentionDays') renderSettings();
    return;
  }
  if (parts[0] === 'ans') {
    const [, qid, k] = parts; const ans = A.answers[qid] = A.answers[qid] || { level: '', evidence: '', evStatus: 'nenhuma', confidence: '', respondent: '', validatedLevel: '', validator: '', validatedAt: '' };
    ans[k] = v;
    if (k === 'evStatus') { if (v === 'verificada' && !ans.validatedAt) ans.validatedAt = todayISO(); if (v !== 'verificada') ans.validatedAt = ''; }
    touch(); updateQMeta(qid); return;
  }
  if (parts[0] === 'opp') { const o = A.opportunities.find(x => x.id === parts[1]); if (!o) return; o[parts[2]] = v; touch(); if (el.dataset.after === 'opp') updateOppSummary(o.id); return; }
  if (parts[0] === 'est') { const r = A.estimate.rows.find(x => x.id === parts[1]); if (!r) return; r[parts[2]] = v; touch(); const t = $('#estTotals'); if (t) t.innerHTML = estTotalsHTML(); return; }
  if (parts[0] === 'par') { const p = A.participants.find(x => x.id === parts[1]); if (!p) return; p[parts[2]] = v; touch(); return; }
  /* caminho no objeto da avaliação */
  if (b === 'context.sector') { changeSector(el); return; }
  const path = b.split('.'); let o = A; for (let i = 0; i < path.length - 1; i++) o = o[path[i]];
  o[path[path.length - 1]] = v;
  if (UI.errors[b] && String(v).trim()) { delete UI.errors[b]; el.removeAttribute('aria-invalid'); const er = document.getElementById(fid(b) + '-err'); if (er) er.remove(); }
  touch();
  const after = el.dataset.after;
  if (after === 'title') renderSaveState();
  if (after === 'est') { const t = $('#estTotals'); if (t) t.innerHTML = estTotalsHTML(); }
  if (after === 'weights') $$('[data-opp-card]').forEach(c => updateOppSummary(c.dataset.oppCard));
  if (after === 'rerender') { renderStep(); renderSaveState(); }
}
async function changeSector(sel) {
  const nv = sel.value, old = A.context.sector; if (nv === old) return;
  const sim = clone(A); sim.context.sector = nv;
  const after = new Set(activeQuestions(sim).map(q => q.id)), affected = activeQuestions(A).filter(q => !after.has(q.id) && hasAnswer(A.answers[q.id]));
  if (affected.length) {
    const ok = await ask('Trocar o segmento?', `${affected.length} resposta(s) de perguntas específicas de “${old}” deixarão de entrar no cálculo.\n\nElas ficam arquivadas nesta avaliação e voltam a valer se “${old}” for escolhido novamente. Para apagá-las, use “Descartar definitivamente” na etapa Questionário.\n\nAs respostas das perguntas gerais são mantidas.`, 'Trocar segmento');
    if (!ok) { sel.value = old; return; }
  }
  A.context.sector = nv;
  if (UI.errors['context.sector'] && nv) delete UI.errors['context.sector'];
  UI.group = ''; touch(`Segmento alterado de “${old || '—'}” para “${nv || '—'}”${affected.length ? `; ${affected.length} resposta(s) arquivada(s)` : ''}`);
  renderStep(); renderSaveState();
}
async function toggleModule(el) {
  const id = el.dataset.module, on = el.checked;
  if (!MODULES.some(m => m.id === id) || id === 'geral') return;
  const before = activeQuestions(A), wasOn = moduleActive(A, id);
  if (on === wasOn) return;
  if (!on) {
    const sim = clone(A); sim.context.selectedModules = selectedModuleIds(A).filter(x => x !== id);
    const afterIds = new Set(activeQuestions(sim).map(q => q.id));
    const affected = before.filter(q => !afterIds.has(q.id) && hasAnswer(A.answers[q.id]));
    if (affected.length && !(await ask(`Desativar ${MODULES.find(m=>m.id===id).name}?`, `${affected.length} resposta(s) deste módulo deixarão de entrar no cálculo. Elas permanecerão arquivadas nesta avaliação e voltarão se o módulo for reativado.`, 'Desativar'))) { el.checked = true; return; }
  }
  const ids = selectedModuleIds(A).filter(x => x !== id);
  if (on) ids.push(id);
  A.context.selectedModules = [...new Set(['geral', ...ids])];
  A.context.ppcp = A.context.selectedModules.includes('ppcp');
  UI.group = ''; touch(on ? `Módulo ${MODULES.find(m=>m.id===id).name} ativado` : `Módulo ${MODULES.find(m=>m.id===id).name} desativado`); renderStep(); renderSaveState();
}
async function togglePPCP(el) { el.dataset.module = 'ppcp'; return toggleModule(el); }

function addContextChoice(list, value) {
  const allowed = ['branches','products','businessModels','specialties'];
  if (!allowed.includes(list)) return;
  const v = str(value,120).trim(); if (!v) return;
  A.context[list] = Array.isArray(A.context[list]) ? A.context[list] : [];
  if (A.context[list].some(x=>x.toLocaleLowerCase('pt-BR')===v.toLocaleLowerCase('pt-BR'))) return toast('Esse item já está selecionado.','warn');
  A.context[list].push(v); touch('Perfil empresarial atualizado'); renderStep();
}
function removeContextChoice(list, value) {
  if (!['branches','products','businessModels','specialties'].includes(list)) return;
  A.context[list] = (A.context[list]||[]).filter(x=>x!==value);
  touch('Item removido do perfil empresarial'); renderStep();
}

async function submitEvaluation() {
  if (!A.context.company || !A.context.company.trim()) { goStep(0); toast('Informe a empresa antes de enviar.', 'err'); return; }
  let token = assessmentToken();
  if (!token) {
    try { await ensureAssessmentSession(); token = assessmentToken(); }
    catch (e) { toast(e.message || 'Não foi possível iniciar a avaliação.', 'err'); return; }
  }
  const btn = $('#btnSubmit'); if (btn) { btn.disabled = true; btn.textContent = 'Enviando…'; }
  try {
    const res = await fetch('/api/assessment-submit', { method:'POST', headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`}, body:JSON.stringify({assessment:A}) });
    const data = await res.json().catch(()=>({}));
    if (!res.ok) throw new Error(data.error || 'Não foi possível concluir o envio.');
    saveDraft();
    try { localStorage.setItem(LAST_RESULT_KEY, token); } catch (storageError) { /* O envio já foi confirmado no servidor. */ }
    clearPublicSession();
    clearInviteFromUrl();
    toast('Avaliação enviada com sucesso. Obrigado!', 'ok');
    if (btn) { btn.textContent = 'Avaliação enviada'; }
    showHome('Avaliação concluída. Você já pode consultar o resultado.');
  } catch (e) { toast(e.message || 'Falha no envio.', 'err'); if (btn) { btn.disabled=false; btn.textContent='Salvar e enviar avaliação'; } }
}

function printReport(format = 'a4') {
  format = 'a4'; // Formato definitivo: A4 vertical
  if (!String(A?.context?.company || '').trim() || !String(A?.context?.sector || '').trim()) {
    goStep(0, { focus: 'f-context-company' });
    return toast('Informe a empresa e o segmento antes de gerar a apresentação.', 'err');
  }
  UI.step = STEPS.findIndex(s => s.id === 'relatorio');
  renderStepNav(); renderStep(); saveDraft();
  const report = $('#reportDoc');
  if (!report) return toast('O relatório não foi montado. Confira o aviso exibido na tela e os dados do contexto.', 'err');
  addLog(A, 'Relatório preparado para impressão em A4 vertical'); touch();
  const oldTitle = document.title;
  document.title = `Mapeamento 360 - ${A.context.company} - ${todayISO()}`;
  document.body.classList.add('printing-report', 'printing-a4');
  const pageStyle = document.createElement('style');
  pageStyle.id = 'report-print-page-style';
  pageStyle.textContent = '@page{size:A4 portrait;margin:13mm 12mm 16mm 12mm;@bottom-center{content:"Página " counter(page);font:8pt Arial,sans-serif;color:#64748b}}';
  document.head.appendChild(pageStyle);
  const cleanup = () => {
    document.body.classList.remove('printing-report', 'printing-a4', 'printing-slides');
    document.title = oldTitle;
    pageStyle.remove();
    window.removeEventListener('afterprint', cleanup);
  };
  window.addEventListener('afterprint', cleanup);
  window.focus();
  requestAnimationFrame(() => window.print());
  setTimeout(cleanup, 120000);
}

const ACTIONS = {
  'add-context-item': b => { const el=document.getElementById(b.dataset.source); if(el && el.value) addContextChoice(b.dataset.list,el.value); },
  'add-context-custom': b => { const el=document.getElementById(b.dataset.source); if(el && el.value.trim()) addContextChoice(b.dataset.list,el.value.trim()); },
  'remove-context-item': b => removeContextChoice(b.dataset.list,b.dataset.value),
  'goto-tab': b => activateTab(b.dataset.tabTarget, true),
  'home-start': () => startPublicFlow(false),
  'home-reassess': () => startPublicFlow(true),
  'home-result': () => viewLastResult(),
  'home-back': () => { saveDraft(); showHome(); },
  'save-assessment': () => saveAssessment(),
  'submit-evaluation': () => submitEvaluation(),
  'new-assessment': () => startNew(),
  'dismiss-resume': () => { UI.resumedAt = ''; renderResume(); },
  'go-step': b => goStep(Number(b.dataset.step)),
  'step-prev': () => goStep(UI.step - 1),
  'step-next': () => nextStep(),
  'add-participant': b => { if (A.participants.length >= LIMITS.participants) return toast('Limite de participantes atingido.', 'err'); const p = { id: uid('p'), name: '', role: '', side: b.dataset.side }; A.participants.push(p); touch('Participante adicionado'); renderStep(); const el = document.getElementById(`par-${p.id}-name`); if (el) el.focus(); },
  'del-participant': async b => { if (!(await ask('Remover participante?', 'O participante será removido e deixará de aparecer como respondente ou validador nas perguntas.', 'Remover', true))) return; const id = b.dataset.id; A.participants = A.participants.filter(p => p.id !== id); Object.values(A.answers).forEach(an => { if (an.respondent === id) an.respondent = ''; if (an.validator === id) an.validator = ''; }); touch('Participante removido'); renderStep(); },
  'pick-group': b => { UI.group = b.dataset.group; renderStep(); const h = $('#gh-' + CSS.escape(UI.group)); if (h) { h.focus({ preventScroll: true }); h.scrollIntoView({ block: 'start' }); } },
  'q-prev': () => { UI.qpage[UI.group] = Math.max(0, (UI.qpage[UI.group] || 0) - 1); renderStep(); focusQuestion(); },
  'q-next': () => { UI.qpage[UI.group] = (UI.qpage[UI.group] || 0) + 1; renderStep(); focusQuestion(); },
  'clear-answer': b => { const q = b.dataset.q; if (A.answers[q]) { A.answers[q].level = ''; } $$(`input[name="lv-${CSS.escape(q)}"]`).forEach(r => r.checked = false); touch(); updateQMeta(q); },
  'discard-archived': async () => { const ids = archivedAnswerIds(A); if (!(await ask('Descartar respostas arquivadas?', `${ids.length} resposta(s) de perguntas inativas serão apagadas desta avaliação. Esta ação não pode ser desfeita.`, 'Descartar', true))) return; ids.forEach(id => delete A.answers[id]); touch(`${ids.length} resposta(s) arquivada(s) descartada(s)`); renderStep(); },
  'confirm-weights': () => { A.weights.reviewedAt = todayISO(); touch('Pesos de priorização revisados'); renderStep(); },
  'add-suggestion': b => { const res = computeAll(A), s = suggestionsFor(A, res).find(x => x.key === b.dataset.key); if (!s) return; const o = newOpportunity({ type: 'sugestao', key: s.key, label: 'Sugestão do sistema · ' + s.label }); o.title = s.title; o.problem = s.reason; o.evidence = s.evidence; o.cause = 'Hipótese a validar com o cliente.'; A.opportunities.push(o); UI.openOpp.add(o.id); touch('Oportunidade adicionada a partir de sugestão'); renderStep(); focusOpp(o.id); },
  'add-opp': () => { if (A.opportunities.length >= LIMITS.opps) return toast('Limite de oportunidades atingido.', 'err'); const o = newOpportunity(); A.opportunities.push(o); UI.openOpp.add(o.id); touch('Oportunidade criada manualmente'); renderStep(); focusOpp(o.id); },
  'delete-opp': async b => { if (!(await ask('Excluir oportunidade?', 'A oportunidade e todos os seus registros (responsáveis, linha de base, resultado) serão apagados desta avaliação.', 'Excluir', true))) return; A.opportunities = A.opportunities.filter(o => o.id !== b.dataset.id); touch('Oportunidade excluída'); renderStep(); },
  'export-plan-csv': () => exportPlanCSV(),
  'add-est': () => { if (A.estimate.rows.length >= LIMITS.estRows) return; const r = newEstRow(); A.estimate.rows.push(r); touch(); renderStep(); const el = document.getElementById(fid(`est:${r.id}:phase`)); if (el) el.focus(); },
  'add-std-phases': () => { STANDARD_PHASES.forEach(p => A.estimate.rows.push(newEstRow(p))); touch('Fases-modelo inseridas na estimativa'); renderStep(); },
  'del-est': async b => { if (!(await ask('Remover linha da estimativa?', 'A linha será apagada.', 'Remover', true))) return; A.estimate.rows = A.estimate.rows.filter(r => r.id !== b.dataset.id); touch(); renderStep(); },
  'open-report': () => {
    if (!String(A?.context?.company || '').trim() || !String(A?.context?.sector || '').trim()) { goStep(0, { focus: 'f-context-company' }); return toast('Informe a empresa e o segmento antes de abrir o relatório.', 'err'); }
    UI.step = STEPS.findIndex(s => s.id === 'relatorio');
    renderStepNav(); renderStep(); saveDraft();
    const report = $('#reportDoc');
    if (!report) return toast('O relatório não foi montado. Confira o aviso exibido na tela e os dados do contexto.', 'err');
    $('#stepHost').scrollIntoView({ block: 'start' });
  },
  'print': () => printReport('a4'),
  'print-a4': () => printReport('a4'),
  'export-assessment': () => exportAssessmentJSON(),
  'prepare-email': () => prepareEmail(),
  'toggle-annex': b => { UI.report.annex = b.checked; renderStep(); },
  'toggle-bench': b => { UI.report.bench = b.checked; renderStep(); },
  'toggle-showall': b => { UI.showAll = b.checked; renderStep(); },
  'toggle-ppcp': b => togglePPCP(b),
  'toggle-module': b => toggleModule(b),
  'export-backup': () => exportBackup(false),
  'export-backup-enc': () => exportBackup(true),
  'export-app-enc': () => exportEncryptedApp(),
  'import-backup': () => $('#importFile').click(),
  'import-legacy': () => importLegacy(),
  'open-saved': b => openSaved(b.dataset.id),
  'export-saved': b => { const it = readList().find(x => x && x.id === b.dataset.id); if (it) download(`Mapeamento_360_Avaliacao_${safeFileName((it.context && it.context.company) || 'avaliacao')}.json`, JSON.stringify(it, null, 2), 'application/json'); },
  'delete-saved': async b => { const it = readList().find(x => x && x.id === b.dataset.id); if (!it) return; if (!(await ask('Excluir avaliação salva?', `“${(it.context && it.context.company) || 'Sem nome'}” será removida da lista deste navegador. ${it.id === A.id ? 'Ela continua aberta como rascunho até você iniciar outra avaliação.' : ''} Esta ação não pode ser desfeita, a menos que exista um backup.`, 'Excluir', true))) return; const r = Store.write(KEYS.list, readList().filter(x => x && x.id !== it.id)); if (!r.ok) return toast('Falha ao excluir (' + r.error + ').', 'err'); if (it.id === A.id) { A.savedAt = ''; touch('Avaliação removida da lista de salvas'); } renderSettings(); toast('Avaliação excluída da lista.'); },
  'purge-expired': async () => { const ret = Number(PREFS.retentionDays); const list = readList(); const exp = list.filter(it => (Date.now() - new Date(it.savedAt || it.updatedAt).getTime()) / 864e5 > ret); if (!exp.length) return; if (!(await ask('Excluir avaliações vencidas?', `${exp.length} avaliação(ões) salvas há mais de ${ret} dias serão apagadas deste navegador. Esta ação não pode ser desfeita.`, 'Excluir', true))) return; const r = Store.write(KEYS.list, list.filter(it => !exp.includes(it))); if (!r.ok) return toast('Falha ao excluir (' + r.error + ').', 'err'); renderSettings(); toast(`${exp.length} avaliação(ões) excluída(s).`); },
  'wipe-all': async () => { if (!(await ask('Apagar todos os dados?', 'Serão apagados deste navegador: a avaliação aberta, todas as avaliações salvas, a base de benchmarks personalizada e as preferências do Mapeamento 360 v3. Dados da v2.4 também serão removidos. Exporte um backup antes se precisar deles. Esta ação não pode ser desfeita.', 'Apagar tudo', true))) return; [...Object.values(KEYS), ...Object.values(LEGACY)].forEach(k => Store.remove(k)); A = newAssessment(); BENCH = clone(BENCHMARK_SEED); PREFS = sanitizePrefs({}); applyTheme(PREFS.theme); applyLogo(PREFS.logo); UI.step = 0; UI.lastDraft = { ok: null, at: '', error: '' }; UI.pending = false; UI.resumedAt = ''; renderAll(); renderSettings(); toast('Todos os dados do Mapeamento 360 foram apagados deste navegador.'); },
  'bench-export': () => download('Mapeamento_360_Benchmarks_' + todayISO() + '.json', JSON.stringify({ schema: 'm360-benchmarks', appVersion: APP.version, exportedAt: nowISO(), records: BENCH }, null, 2), 'application/json'),
  'bench-template': () => download('Modelo_Benchmarks_Mapeamento_360.csv', '﻿' + BENCH_FIELDS.join(';') + '\r\n', 'text/csv;charset=utf-8'),
  'bench-import': () => $('#benchFile').click(),
  'bench-reset': async () => { if (!(await ask('Restaurar base inicial?', 'A base atual será substituída pelos registros iniciais conferidos em 27/10/2026. Registros importados serão perdidos, a menos que tenham sido exportados.', 'Restaurar', true))) return; BENCH = clone(BENCHMARK_SEED); saveBench(); renderBench(); },
  'bench-clear': () => { UI.benchFilter = { q: '', source: '', status: '' }; renderBench(); },
  'bench-del': async b => { if (!(await ask('Excluir registro?', 'O registro será removido da base deste navegador.', 'Excluir', true))) return; BENCH = BENCH.filter(r => r.id !== b.dataset.id); saveBench(); renderBench(); },
  'bench-bar': b => { const ids = b.dataset.ids.split(','); const r = BENCH.find(x => x.id === ids[0]); if (r) { UI.benchFilter.q = r.indicator; UI.benchFilter.source = r.source; renderBench(); toast('Tabela filtrada por ' + r.source + ' · ' + r.indicator); } }
};
function focusQuestion() { const q = $('#stepHost .question .q-title'); if (q) { q.tabIndex = -1; q.focus({ preventScroll: true }); q.closest('.qgroup').scrollIntoView({ block: 'start' }); } }
function focusOpp(id) { const c = document.querySelector(`[data-opp-card="${CSS.escape(id)}"]`); if (c) { c.scrollIntoView({ block: 'center' }); const el = c.querySelector('input'); if (el) el.focus({ preventScroll: true }); } }

function bindEvents() {
  document.addEventListener('click', e => {
    const help = e.target.closest('[data-help]'); if (help) { e.preventDefault(); helpPop && helpPop.dataset.src === help.dataset.help ? closeHelp() : (openHelp(help), helpPop.dataset.src = help.dataset.help); return; }
    if (helpPop && !e.target.closest('.help-pop')) closeHelp();
    const tab = e.target.closest('.main-tab'); if (tab) { activateTab(tab.dataset.tab); return; }
    const act = e.target.closest('[data-action]'); if (!act || act.disabled) return;
    if (act.type === 'checkbox') return; // tratado em change
    const fn = ACTIONS[act.dataset.action]; if (fn) { e.preventDefault(); fn(act); }
  });
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') closeHelp();
    const g = e.target.closest && e.target.closest('g[data-action]'); if (g && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); ACTIONS['bench-bar'](g); }
    const tab = e.target.closest && e.target.closest('.main-tab');
    if (tab && ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(e.key)) { e.preventDefault(); const tabs = $$('.main-tab'), i = tabs.indexOf(tab); const n = e.key === 'Home' ? 0 : e.key === 'End' ? tabs.length - 1 : (i + (e.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length; tabs[n].focus(); activateTab(tabs[n].dataset.tab); }
  });
  document.addEventListener('input', e => {
    const el = e.target;
    if (el.id === 'f-custom-product') {
      const term = el.value.trim();
      const match = document.getElementById('f-product-match');
      const web = document.getElementById('f-product-web-search');
      if (web) web.href = 'https://www.google.com/search?q=' + encodeURIComponent(term ? term + ' fabricante equipamento produto' : 'produtos e equipamentos industriais');
      if (match) {
        if (!term) match.textContent = 'A busca sugere termos semelhantes, mas você pode cadastrar qualquer nome.';
        else {
          const catalog = [...new Set([...PRODUCT_CATALOG_GLOBAL,...Object.values(PRODUCT_CATALOG).flat()])];
          const best = catalog.map(name => ({name,score:productSimilarity(term,name)})).sort((a,b)=>b.score-a.score)[0];
          match.textContent = best && best.score >= 25 ? `Sugestão do catálogo: ${best.name} · ${best.score}% de similaridade. Você pode usar a sugestão ou manter “${term}”.` : 'Nenhuma correspondência forte no catálogo. O termo informado será aceito como produto personalizado.';
        }
      }
      return;
    }
    if (el.dataset.bench) { UI.benchFilter[el.dataset.bench] = el.value; if (el.tagName === 'INPUT') { clearTimeout(el._t); el._t = setTimeout(() => { renderBench(); const x = $('#bf-q'); if (x) { x.focus(); x.setSelectionRange(x.value.length, x.value.length); } }, 250); } return; }
    if (el.dataset.bind && (el.tagName === 'TEXTAREA' || (el.tagName === 'INPUT' && !['radio', 'checkbox', 'date'].includes(el.type)))) setBound(el);
  });
  document.addEventListener('change', e => {
    const el = e.target;
    if (el.id === 'importFile') { const f = el.files && el.files[0]; el.value = ''; if (f) importBackupFile(f); return; }
    if (el.id === 'benchFile') { const f = el.files && el.files[0]; el.value = ''; if (f) importBenchFile(f); return; }
    if (el.dataset.bench && el.tagName === 'SELECT') { UI.benchFilter[el.dataset.bench] = el.value; renderBench(); return; }
    if (el.dataset.benchchart) { UI.benchChart[el.dataset.benchchart] = el.value; renderBench(); const x = document.getElementById(el.id); if (x) x.focus(); return; }
    if (el.matches('input[type=radio][data-q]')) { const q = el.dataset.q; const ans = A.answers[q] = A.answers[q] || { level: '', evidence: '', evStatus: 'nenhuma', confidence: '', respondent: '', validatedLevel: '', validator: '', validatedAt: '' }; ans.level = ['ns', 'na'].includes(el.value) ? el.value : Number(el.value); touch(); updateQMeta(q); return; }
    if (el.type === 'checkbox' && el.dataset.action) { const fn = ACTIONS[el.dataset.action]; if (fn) fn(el); return; }
    if (el.dataset.bind && (el.tagName === 'SELECT' || ['radio', 'checkbox', 'date', 'number'].includes(el.type))) setBound(el);
  });
  document.addEventListener('toggle', e => { const d = e.target; if (d.dataset && d.dataset.ev) d.open ? UI.openEv.add(d.dataset.ev) : UI.openEv.delete(d.dataset.ev); if (d.dataset && d.dataset.oppCard) d.open ? UI.openOpp.add(d.dataset.oppCard) : UI.openOpp.delete(d.dataset.oppCard); }, true);
  window.addEventListener('beforeunload', e => { if (UI.pending) saveDraft(); if (UI.lastDraft.ok === false) { e.preventDefault(); e.returnValue = ''; } });
  window.addEventListener('resize', closeHelp);
}

/* ---------- inicialização ---------- */
function showHome(message = '') {
  const home = $('#homeScreen');
  if (home) home.hidden = false;
  const assessment = $('#panel-assessment'), benchmarks = $('#panel-benchmarks');
  if (assessment) assessment.hidden = true;
  if (benchmarks) benchmarks.hidden = true;
  const tabs = $('#mainTabs'); if (tabs) tabs.hidden = true;
  const back = $('#resultBack'); if (back) back.hidden = true;
  document.body.classList.remove('result-readonly');
  const notice = $('#homeNotice'); if (notice) notice.textContent = message;
  document.title = 'Mapeamento 360';
}
function showAssessment() {
  const home = $('#homeScreen'); if (home) home.hidden = true;
  const tabs = $('#mainTabs'); if (tabs) tabs.hidden = false;
  const back = $('#resultBack'); if (back) back.hidden = true;
  document.body.classList.remove('result-readonly');
  activateTab('assessment');
  ['.assess-bar', '#resumeHost', '#stepNav', '.step-actions'].forEach(sel => { const el = $(sel); if (el) el.hidden = false; });
}
async function startPublicFlow(reassess) {
  clearPublicSession();
  clearInviteFromUrl();
  A = newAssessment(); addLog(A, reassess ? 'Nova avaliação iniciada para reavaliação' : 'Nova avaliação iniciada');
  UI.step = 0; UI.group = ''; UI.qpage = {}; UI.errors = {}; UI.resumedAt = '';
  UI.openEv.clear(); UI.openOpp.clear();
  saveDraft(); renderAll(); showAssessment();
  $('#stepHost').scrollIntoView({ block: 'start' });
}
function displayResultAssessment(raw, submittedAt = '') {
  REPORT_SUBMITTED_AT = submittedAt || '';
  A = sanitizeAssessment(raw);
  UI.step = STEPS.findIndex(step => step.id === 'relatorio');
  UI.group = ''; UI.errors = {}; UI.resumedAt = '';
  renderAll();
  const home = $('#homeScreen'); if (home) home.hidden = true;
  const tabs = $('#mainTabs'); if (tabs) tabs.hidden = true;
  const back = $('#resultBack'); if (back) back.hidden = false;
  activateTab('assessment');
  ['.assess-bar', '#resumeHost', '#stepNav', '.step-actions'].forEach(sel => { const el = $(sel); if (el) el.hidden = true; });
  document.body.classList.add('result-readonly');
  document.title = 'Resultado · Mapeamento 360';
  $('#stepHost').scrollIntoView({ block: 'start' });
}
async function viewLastResult() {
  const token = lastResultToken();
  if (!token || !validSessionToken(token)) {
    const notice = $('#homeNotice');
    if (notice) notice.textContent = 'Não encontramos um resultado salvo neste navegador. Para consultar, use o link individual recebido para a avaliação.';
    return;
  }
  const button = $('[data-action="home-result"]');
  if (button) { button.disabled = true; button.textContent = 'Carregando…'; }
  try {
    const response = await fetch('/api/assessment-result', { headers: { 'Authorization': 'Bearer ' + token }, cache: 'no-store' });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.assessment) throw new Error(data.error || 'Não foi possível carregar o resultado.');
    displayResultAssessment(data.assessment, data.submitted_at);
  } catch (error) {
    const notice = $('#homeNotice');
    if (notice) notice.textContent = error.message || 'Não foi possível consultar o resultado.';
  } finally {
    if (button) { button.disabled = false; button.textContent = 'Ver resultado'; }
  }
}

function init() {
  PREFS = loadPrefs(); applyTheme(PREFS.theme); applyLogo(PREFS.logo);
  BENCH = loadBench();
  const d = Store.read(KEYS.draft, null);
  A = null;
  if (d && d.assessment) { try { A = sanitizeAssessment(d.assessment); UI.step = Math.max(0, Math.min(STEPS.length - 1, Number(d.ui && d.ui.step) || 0)); UI.resumedAt = A.updatedAt; UI.lastDraft = { ok: true, at: d.savedAt || A.updatedAt, error: '' }; } catch (e) { A = null; } }
  if (!A) { A = newAssessment(); addLog(A, 'Avaliação criada'); }
  if (!Store.available()) { UI.lastDraft = { ok: false, at: nowISO(), error: 'armazenamento indisponível' }; }
  document.title = `${APP.name} · Diagnóstico empresarial v${APP.version}`;
  $('#versionBadge').textContent = `Autoavaliação · v${APP.version}`;
  bindEvents();
  let tab = 'assessment'; try { tab = sessionStorage.getItem('m360.tab') || 'assessment'; } catch (e) { }
  if (!['assessment', 'benchmarks'].includes(tab)) tab = 'assessment';
  renderAll();
  // Links individuais com token continuam abrindo diretamente a avaliação.
  // O endereço público principal abre somente a tela inicial.
  const params = new URLSearchParams(window.location.search);
  if (params.has('admin-report')) {
    try {
      const stored = sessionStorage.getItem('m360.admin.report');
      sessionStorage.removeItem('m360.admin.report');
      const payload = stored ? JSON.parse(stored) : null;
      if (!payload || !payload.assessment) throw new Error('O resultado administrativo não está disponível nesta aba. Volte ao painel e abra novamente.');
      displayResultAssessment(payload.assessment, payload.submitted_at);
    } catch (error) {
      showHome(error.message || 'Não foi possível abrir o resultado administrativo.');
    }
  } else if (params.has('token')) showAssessment();
  else showHome();
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
